/*
 * Ateria dish photos: recipe id -> { src, credit? }.
 *
 * This file is GENERATED by `node tools/photos_index.js` from the files in img/food/ (one photo per recipe, named <recipe id>.jpg).
 * Recipes without a photo keep the drawn ingredient pictures, so the app works with none, some or all of them.
 * `credit` is shown under the photo only when the photo's licence asks for it (img/food/credits.json).
 */
(function (g) {
  const A = (g.Ateria = g.Ateria || {});
  A.PHOTOS = {};
  A.photo = function (id) { return Object.prototype.hasOwnProperty.call(A.PHOTOS, id) ? A.PHOTOS[id] : null; };
})(typeof window !== 'undefined' ? window : globalThis);
